def S(key, name, group, image, alt, card, intro, pains, must, gallery, package, tips, case, faqs, related, stand_in=False):
    return dict(key=key, name=name, group=group, image=image, alt=alt, card=card, intro=intro, pains=pains,
                must=must, gallery=gallery, package=package, tips=tips, case=case, faqs=faqs, related=related,
                stand_in=stand_in)


